Method.Implementation:
if $data(%ISCName)#2 {
    $$$RemoveClsTempNodes
}
do $system.OBJ.CompilePackage("%IPM","ckf")
if $data(%ISCName)#2 {
    $$$AddClsTempNodes
}

// Explicitly force DeveloperMode to 0 to avoid loading tests
// Do not map here when installed from installer; that's handled via Installer XDatas if/when needed
quit ##class(%IPM.Main).Shell("load "_pDirectoryName_" -DDeveloperMode=0 -DNoMapping=1")

if ##class(%IPM.Utils.Migration).HasLegacyZPMPackage() {
    quit ##class(%IPM.Main).Shell("enable -globally -map")
}
quit $$$OK

if ..ValidatePythonRuntime() {
    try {
        set installed = ..ORASInstalled()
    } catch e {
        // A wheel install cannot succeed while the packages are unreadable, so report rather than reinstall
        set installed = 1
        write !!,"WARNING: Unable to check whether the ORAS Python components are installed. Not all IPM features will be available. "_e.DisplayString(),!
    }
    if 'installed {
        // Need to run in a background process to pick up new %IPM.Storage.Module definition
        write !,"Installing ORAS Python components..."
        job ..InitializeAndSignal()
        set result = $system.Event.WaitMsg("",30)
        set $listbuild(msg,sc) = result
        if (msg = 0) {
            write !,"ORAS installation timed out and may not have completed successfully."
        } elseif $$$ISERR(sc) {
            write !,"An error occurred installing Python dependencies: ",$system.Status.GetErrorText(sc)
        } else {
            write " done."
        }
    }
} else {
    write !!,"WARNING: Flexible Python Runtime is not configured on this instance with a valid Python version (>=3.9). Not all IPM features will be available. If you wish to use ORAS registries, configure Flexible Python Runtime and then reinstall IPM.",!
}
quit $$$OK

if '$$$isWINDOWS {
    quit $$$OK
}
set pythonDir = ##class(%File).NormalizeDirectory("python", ##class(%File).ManagerDirectory())
if '##class(%File).DirectoryExists(pythonDir) {
    quit $$$OK
}

// Unique per call, so a late signal from a timed-out job cannot reach a later wait
set eventName = $name(^IPM.ResetPyPerms($job, $zhorolog))
do $system.Event.Create(eventName)
write !,"Resetting permissions of Python packages..."
try {
    // JOB can fail to start transiently (e.g. the process table is briefly full), so retry a few times
    set maxAttempts = 3
    for attempt=1:1:maxAttempts {
        job ..ResetPythonPermissionsAndSignal(pythonDir, eventName)::10
        quit:$test
        set jobError = $zerror
        hang 1
    }
    if '$test {
        $$$ThrowStatus($$$ERROR($$$GeneralError, $$$FormatText("Job to reset permissions of %1 did not start after %2 attempts: %3", pythonDir, maxAttempts, jobError)))
    }
    set child = $zchild
    set deadline = $zhorolog + timeout
    // Poll until the job signals a result, the job's process ends (so a crashed job cannot hang this), or timeout elapses
    do {
        set result = $system.Event.WaitMsg(eventName, 1)
    } while ($listget(result, 1) '= 1) && $data(^$job(child)) && ($zhorolog < deadline)
    if $listget(result, 1) '= 1 {
        // The job may have signaled just before exiting
        set result = $system.Event.WaitMsg(eventName, 0)
    }
    if $listget(result, 1) '= 1 {
        if $zhorolog >= deadline {
            $$$ThrowStatus($$$ERROR($$$GeneralError, $$$FormatText("Timed out after %1 seconds waiting for the job to reset permissions of %2", timeout, pythonDir)))
        } else {
            $$$ThrowStatus($$$ERROR($$$GeneralError, $$$FormatText("Job %1 exited without reporting a result for resetting permissions of %2", child, pythonDir)))
        }
    }
    $$$ThrowOnError($listget(result, 2))
    write " done."
} catch ex {
    write !!,"WARNING: Unable to reset the permissions of Python packages in "_pythonDir_". Entries created by a different Windows account (for example, a manual irispip run, or an earlier IPM install that ran as a different account) may remain unreadable outside that account, which can make ORAS installs fail with a PermissionError. To fix this manually, run 'icacls "_pythonDir_" /reset /T' as an administrator. "_ex.DisplayString(),!
}
do $system.Event.Delete(eventName)
quit $$$OK

set sc = $$$OK
try {
    do ##class(%IPM.Utils.Module).ResetProtectedPermissions(pythonDir)
} catch ex {
    set sc = ex.AsStatus()
}
do $system.Event.Signal(eventName, sc)

try {
    set version = ..PythonMajorMinorVersion()
    set major = +$piece(version, ".", 1)
    set minor = +$piece(version, ".", 2)
    if (major < 3) || ((major = 3) && (minor < 9)) {
        write !!,"WARNING: Python version "_version_" is not supported. IPM requires Python 3.9 or higher.",!
        return 0
    }
} catch e {
    return 0
}
return 1

try:
  # oras alone imports as an empty namespace package when its __init__.py is unreadable
  import oras.provider
  return True
except ImportError:
  return False

try {
    set module = ##class(%IPM.Storage.Module).NameOpen("zpm")
    if '$isobject(module) {
        return 1
    }

    set version = ##class(%IPM.General.SemanticVersion).FromString(..#VERSION)
    if $isobject(version) {
        return version.Follows(module.Version)
    }

} catch ex {

}
quit 1

set rs = ##class(%File).FileSetFunc(pPath)
while rs.%Next() {
    if rs.Type="D" {
        do ..CollectPackage(rs.Name, .pList, pRoot)
    } else {
        #; Set $LISTBUILD(url) = $SYSTEM.CSP.FilenameToUrls(rs.Name)
        set pList($increment(pList)) = $listbuild(rs.Name, $extract(rs.Name, $length(pRoot) + 1, *))
    }
}

set pFolder = ..CreateTempDir()

for i=1:1:..#FILESCOUNT {
    set xdata = ##class(%Dictionary.XDataDefinition).%OpenId($classname()_"||Data"_i)
    set name = xdata.Description
    set fileName = pFolder_name

    set tParentFolder = ##class(%File).ParentDirectoryName(fileName)
    if '##class(%File).DirectoryExists(tParentFolder) {
        do ##class(%File).CreateDirectoryChain(tParentFolder)
    }

    set tmpFile = ##class(%File).TempFilename("gz")

    set stream = ##class(%Stream.FileBinary).%New()
    set stream.Filename = tmpFile
    set prev = ""
    set chunkSize = 30400
    do {
        set data = prev
        if 'xdata.Data.AtEnd {
            set data = data _ xdata.Data.Read()
        }
        set data = $zstrip(data, "*C")
        set prev = $extract(data, chunkSize + 1, *)
        set data = $extract(data, 1, chunkSize)
        set chunk = $system.Encryption.Base64Decode(data)
        do stream.Write(chunk)
    } while (prev'="")||('xdata.Data.AtEnd)
    do stream.%Save()

    set gzip = ##class(%Stream.FileBinaryGzip).%New()
    set gzip.Filename = tmpFile

    if $piece(fileName,".",*) = "whl" {
        // TODO: generalize to other binary file types?
        set fs = ##class(%Stream.FileBinary).%New()
    } else {
        set fs = ##class(%Stream.FileCharacter).%New()
    }
    set fs.Filename = fileName
    do fs.CopyFromAndSave(gzip)

    do ##class(%File).Delete(tmpFile)
}
quit $$$OK

set tDir = $$$FileTempDir

/// In some cases, the $zu(140, 17) will return a negated error code.
/// For example, it can return -28, where 28 is Unix errno for "no space left on device".
if tDir = ("-" _ -tDir) {
    throw ##class(%Exception.General).%New("Failed to create temporary directory. Error code: " _ -tDir)
}
return ##class(%File).NormalizeDirectory(tDir)

set sc = $$$OK
// Get list of all namespaces
new $namespace
set $namespace = "%SYS"
set status = ##class(%SYS.Namespace).ListAll(.nsList)
if $$$ISERR(status) {
    return status
}

// Iterate through each namespace and remove old mappings
set namespace = ""
for {
    set namespace = $order(nsList(namespace))
    if namespace = "" {
        quit
    }
    set $namespace = namespace
    // check if IPM is installed in this namespace
    if '$$$comClassDefined("%IPM.Main") {
        continue
    }

    // Cleanup old mappings from oddStudioDocument
    set key = ""
    for {
        set key = $order(^oddStudioDocument(key))
        quit:key=""
        if (key["%ZPM.PackageManager") || (key["%ZHSLIB.PackageManager") {
            kill ^oddStudioDocument(key)
        }
    }

    // These mappings were suggested as a temporary workaround for IRIS 2023.x,
    // but whose underlying issues have been resolved in 2024.1 and later.
    // %IPM.Utils.Module ships in the src payload imported later in this manifest, so
    // on some upgrade paths the class/method may not yet exist when this runs. Tolerate
    // that with a try/catch rather than reordering, since cleanup must precede the import.
    try {
        set status = ##class(%IPM.Utils.Module).RemoveGlobalMapping($namespace,"oddStudioDocument:(BEGIN):(""%ZP"")","IRISLIB")
        if $$$ISERR(status) {
            set sc = $$$ADDSC(sc, status)
        }
        set status = ##class(%IPM.Utils.Module).RemoveGlobalMapping($namespace,"oddStudioDocument:(""%ZP""):(""A"")","IRISSYS")
        if $$$ISERR(status) {
            set sc = $$$ADDSC(sc, status)
        }
        set status = ##class(%IPM.Utils.Module).RemoveGlobalMapping($namespace,"oddStudioDocument:(""Ens""):(""Ent"")","ENSLIB")
        if $$$ISERR(status) {
            set sc = $$$ADDSC(sc, status)
        }
        set status = ##class(%IPM.Utils.Module).RemoveGlobalMapping($namespace,"oddStudioDocument",namespace)
        if $$$ISERR(status) {
            // this mapping deletion will fail if there are still sub-mappings present
            // so we can ignore errors here
        }
    } catch e {
        // %IPM.Utils.Module (or RemoveGlobalMapping) not available yet on this upgrade path; skip
        write !,"WARNING: CleanupOldMappings caught exception in ",namespace,": ",e.DisplayString()
    }
}

return sc

// Scripts are bash; skip entirely on non-Unix platforms.
if '$$$isUNIX {
    quit $$$OK
}
try {
    // The scripts are staged under ${ipmdir}bin/ by <FileCopy> in module.xml.
    set module = ##class(%IPM.Storage.Module).NameOpen(..#MODULENAME, , .openSC)
    $$$ThrowOnError(openSC)
    if '$isobject(module) {
        write !,"Could not resolve module directory for script installation."
        quit
    }
    set binDir = ##class(%Library.File).NormalizeDirectory($system.Util.DataDirectory() _ "ipm/" _ module.Name _ "/" _ module.VersionString _ "/bin")

    set homeDir = $system.Util.GetEnviron("HOME")
    if homeDir = "" {
        write !,"$HOME not set, skipping script installation."
        quit
    }
    set localBin = ##class(%Library.File).NormalizeDirectory(homeDir _ "/.local/bin")

    // ~/.local/bin is the XDG standard for user scripts; create it if absent.
    if '##class(%Library.File).DirectoryExists(localBin) {
        if '##class(%Library.File).CreateDirectoryChain(localBin) {
            $$$ThrowStatus($$$ERROR($$$GeneralError, "Could not create directory: " _ localBin))
        }
    }

    // ~/bin is on PATH in the IRIS container; ~/.local/bin covers most Unix/Linux distros.
    // We skip ~/bin if it doesn't exist to avoid creating unexpected directories on systems that don't use it.
    set homeBin = ##class(%Library.File).NormalizeDirectory(homeDir _ "/bin")

    for script = "ipm","iriscli" {
        set src = binDir _ script
        if '##class(%Library.File).Exists(src) {
            write !,"Warning - source script not found: ",src
            continue
        }
        for targetDir = localBin,homeBin {
            if (targetDir = homeBin) && '##class(%Library.File).DirectoryExists(homeBin) {
                continue
            }
            set dest = targetDir _ script
            if '##class(%Library.File).CopyFile(src, dest, 1) {
                write !,"Warning - could not copy ",script," to ",targetDir
                continue
            }
            set cmd = $listbuild("chmod", "+x", dest)
            $$$ThrowOnError(##class(%IPM.Utils.Module).RunCommand(, cmd, , , .rc))
        }
    }
    write !,"Installed ipm and iriscli scripts to ",localBin
} catch ex {
    // Swallow all errors ? a failed script copy must not fail the module install.
    write !,"Warning - script installation failed: ",ex.DisplayString()
}
quit $$$OK
